// mintClientCredentialsToken POSTs grant_type=client_credentials to the
// token endpoint and returns the parsed token response.
func mintClientCredentialsToken(httpClient *http.Client, tokenURL, clientID, clientSecret string) (*tokenResponse, error) {
	// hand-fix: Asio requires client_id/client_secret in a JSON body.
	req, err := client.NewAsioTokenRequest(context.Background(), tokenURL, clientID, clientSecret, resolveClientCredentialsScope(), resolveClientCredentialsUserAgent())
	if err != nil {
		return nil, fmt.Errorf("building token request: %w", err)
	}

	resp, err := cliutil.OAuthTokenHTTPClient(httpClient).Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling token endpoint: %w", err)
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("token endpoint returned HTTP %d: %s", resp.StatusCode, client.RedactTokenBody(string(body), clientSecret)) // hand-fix: redact
	}
	var tok tokenResponse
	if err := json.Unmarshal(body, &tok); err != nil {
		return nil, fmt.Errorf("parsing token response: %w", err)
	}
	if tok.AccessToken == "" {
		return nil, fmt.Errorf("token response missing access_token")
	}
	return &tok, nil
}

